"""Results front page — reports/DASHBOARD.md (register 58). Regenerated by
every Part C run. OPERATOR-FIRST, one page.

RULE: the dashboard contains NO number that is not in a stamped artifact —
it is a table of contents with headlines, never a source. Every figure
cites the artifact it was lifted from.
"""

import json
import os
import time

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SB = os.path.join(ROOT, "reports", "scoreboard")


def _load(name, base=SB):
    try:
        return json.load(open(os.path.join(base, name)))
    except Exception:
        return None


def generate():
    from backtest.scoreboard import (register_status, register_labels,
                                     parse_questions)
    from engine.signal_watch import (FIRING_CONDITIONS, EVENT_DERIVED_ROWS,
                                     DERIVED_FIRES)
    sb = _load("hypothesis_performance.json")
    reg = register_status()
    labels = register_labels()
    qs = parse_questions()
    L = ["# DASHBOARD — results front page", "",
         "Terms: [docs/GLOSSARY.md](docs/GLOSSARY.md) — reading-order "
         "item 2.", "",
         "Regenerated by every Part C run. **No number here is a source — "
         "every figure lives in a stamped artifact; this page only points "
         "and headlines.**", ""]

    # (a) headline state
    n_sig = len(FIRING_CONDITIONS) + len(EVENT_DERIVED_ROWS) \
        + len(DERIVED_FIRES)
    n_q = sum(len(v) for v in qs.values())
    span = "—"
    eng = "—"
    if sb:
        eng = sb.get("engine_commit", "—")[:9]
        home = sb.get("instruments", {}).get("uk100fut", {})
        sp = home.get("store_span_1min")
        if sp:
            span = f"{sp[0][:10]} → {sp[1][:10]}"
    L += ["## State", "",
          f"- **{len(reg)} hypotheses · {n_sig} signal configurations · "
          f"{n_q} questions** (docs/hypothesis_register.md)",
          f"- Home 1M data span: {span} · scoreboard engine `{eng}` · "
          f"page generated {time.strftime('%Y-%m-%d %H:%M UTC', time.gmtime())}",
          ""]

    # (b) the board — one line per hypothesis (home instrument, canonical).
    # POINTS-FIRST (register 59): forward net points at 3xATR leads;
    # precision lift is the secondary read. Points from the stop-width
    # ladder (reports/SIGNAL_POINTS.md — the first drill-down).
    sp = _load("signal_points.json")
    sp_home = {}
    if sp:
        for res in sp.get("results", []):
            if res.get("instrument") == "uk100fut":
                sp_home = res.get("signals", {})

    def _points_at(n, width, win):
        """Sum net/n across ALL of H<n>'s signals (all-or-none, no
        best-of), plus per-session nets — from signal_points.json."""
        import re as _re
        tot = cnt = 0.0
        have = False
        sess = {}
        for key, row in sp_home.items():
            if not _re.fullmatch(rf"S\d+-H{n}", key) or "note" in row:
                continue
            cell = row.get(width, {}).get(win)
            if not cell:
                continue
            have = True
            tot += cell["net_pts"]
            cnt += cell["n"]
            for s, v in cell.get("by_session", {}).items():
                sess[s] = round(sess.get(s, 0.0) + v["net_pts"], 1)
        return (round(tot, 1), int(cnt), sess) if have else None

    L += ["## The board (home instrument; away instruments PROVISIONAL — "
          "see the scoreboard). DOCTRINE ORDER (register 62 — edge = "
          "consistency): initiation lift, then median-per-trade ≤3×ATR, "
          "then baseline clearance; net is context. Nothing here "
          "re-grades — the governance sitting changes what gets acted "
          "on. Board numbers are the harvest ladder's — fill model "
          "PESSIMISTIC (register 65); census reach cells (the scalp "
          "clocks) are touch=fill OPTIMISTIC — not comparable. **The "
          "drill-down is [SIGNAL_POINTS.md](SIGNAL_POINTS.md)**", "",
          "| H | init lift (best measurable cell) | S0 med/trade @3× "
          "fwd | baseline clearance (S0 @3× fwd) | context: fwd net @3× "
          "(n); sessions | fwd trend | status |",
          "|---|---|---|---|---|---|---|"]
    if sb:
        home = sb.get("instruments", {}).get("uk100fut", {})
        sigs = home.get("signals", {})
        import re
        for n in sorted(reg):
            best = None
            trend = "→"
            for w in ("backtest", "forward"):
                blk = sigs.get(w, {})
                mv = blk.get("_moves", {})
                for key, r in blk.items():
                    if key.startswith("_") or not isinstance(r, dict):
                        continue
                    m = re.fullmatch(rf"S(\d+)-H{n}( \(either-dir\))?", key)
                    if not m or not r.get("n_fires"):
                        continue
                    ini = r.get("initiation")
                    if not ini or ini.get("pct") is None:
                        continue
                    ch = (r.get("conditioned_chance_init_pct")
                          or (mv.get("initiation_base_either_pct")
                              if r["grading"] == "either-direction"
                              else mv.get(
                                  "initiation_base_per_direction_pct")))
                    if ch is None or ini["of"] < 20:
                        continue
                    lift = round(ini["pct"] - ch, 1)
                    if best is None or abs(lift) > abs(best[0]):
                        best = (lift, key, w, ini["of"])
            # trend arrow: forward vs backtest initiation lift of the
            # hypothesis's S0 row
            def _lift(w, key):
                blk = sigs.get(w, {})
                r = blk.get(key)
                mv = blk.get("_moves", {})
                if not r or not r.get("n_fires"):
                    return None
                ini = r.get("initiation")
                if not ini or ini.get("pct") is None:
                    return None
                ch = (r.get("conditioned_chance_init_pct")
                      or (mv.get("initiation_base_either_pct")
                          if r["grading"] == "either-direction"
                          else mv.get("initiation_base_per_direction_pct")))
                return None if ch is None else ini["pct"] - ch
            s0 = f"S0-H{n}"
            lb, lf = _lift("backtest", s0), _lift("forward", s0)
            if lb is not None and lf is not None:
                trend = "↑" if lf > lb + 2 else "↓" if lf < lb - 2 else "→"
            lift_cell = (f"**{best[1]} {best[2]} {best[0]:+.1f}pp** "
                         f"(n={best[3]})"
                         if best else "no measurable cell (n<20)")
            # doctrine axes (ii) and (iii): S0's forward 3x cell from
            # the ladder — median-per-trade and matched-floor clearance
            s0_row = sp_home.get(f"S0-H{n}", {})
            s0_cell = s0_row.get("3x", {}).get("forward")
            mb = s0_row.get("matched_baseline", {}).get("forward")
            if s0_cell:
                dim0 = "°" if s0_cell["n"] < 20 else ""
                med_cell = (f"{dim0}{s0_cell['median_pts']:+.2f} "
                            f"(n{s0_cell['n']})")
            else:
                med_cell = "—"
            if s0_cell and mb:
                lo, hi = mb.get("baseline_range_3x",
                                [mb["baseline_median_3x"]] * 2)
                clr = round(s0_cell["median_pts"] - hi, 2)
                clr_cell = (f"{clr:+.2f} above {mb['name']} max"
                            if clr > 0 else
                            f"{clr:+.2f} vs {mb['name']} max — inside "
                            f"the floor's noise")
            else:
                clr_cell = "—"
            pts = _points_at(n, "3x", "forward")
            if pts:
                net, cnt, sess = pts
                dim = "°" if cnt < 20 else ""
                ctx_cell = f"{dim}{net:+.1f} (n{cnt})"
                if len(sess) == 1:
                    s_only = next(iter(sess))
                    ctx_cell += f"; {s_only} only"
                elif sess:
                    hi_s = max(sess, key=sess.get)
                    lo_s = min(sess, key=sess.get)
                    ctx_cell += (f"; best {hi_s} {sess[hi_s]:+.1f}, "
                                 f"worst {lo_s} {sess[lo_s]:+.1f}")
            else:
                ctx_cell = "—"
            L.append(f"| H{n} | {lift_cell} | {med_cell} | {clr_cell} "
                     f"| {ctx_cell} | {trend} | {labels.get(n, '-')} |")
    L.append("")

    # (c) open questions with clocks
    L += ["## Open questions (clocks = accrued vs required; grading "
          "conditions authoritative in the register entries)", ""]

    def _sess_fires(inst, key, sess):
        if not sb:
            return None
        blk = (sb.get("instruments", {}).get(inst, {})
               .get("signals_by_session", {}).get("forward", {})
               .get(sess, {}))
        r = blk.get(key)
        return r.get("n_fires") if r else 0

    def _journal_q2h11():
        import csv as _csv
        p_ = os.path.join(ROOT, "reports", "trades.csv")
        if not os.path.exists(p_):
            return 0
        import pandas as _pd
        mint = _pd.Timestamp("2026-08-28T00:00:00Z")   # Q2-H11 mint
        n_ = 0
        for r in _csv.DictReader(open(p_)):
            if (r["instrument"] == "ger40fut"
                    and r["sentence_id"] == "S0-H11"
                    and r["variant"] == "R-NEXIT-EARLY"
                    and r["session"] == "london"
                    and _pd.Timestamp(r["open_ts"]) >= mint):
                n_ += 1
        return n_

    def _bp_fwd_fires(inst, key):
        bp = _load("bar_persistence.json")
        for res in (bp or {}).get("results", []):
            if res.get("instrument") == inst:
                whole = (res.get("signals", {}).get(key, {})
                         .get("forward", {}) or {}).get("whole")
                return whole.get("n_fires", 0) if whole else 0
        return 0
    q_lines = [
        ("Q1-H1", "≥30 post-validation fwd episodes/instrument — ALL "
         "instruments VALIDATED (reg 40 amdts): every leg's clock LIVE "
         "from the next sync"),
        (f"Q1-H{7}", "same gate as Q1-H1 — all legs LIVE"),
        ("Q1-H11", f"≥30 fwd Overlap fires (home accrued: "
         f"{_sess_fires('uk100fut', 'S0-H11', 'overlap')})"),
        (f"Q2-H{9}", "≥30 fwd NY-session fires on nas100 — VALIDATED "
         "2026-08-25: clock LIVE from the next sync"),
        (f"Q1-H{6}", "**GRADED: PARTIAL** (YES 2026-08-27 amended "
         "same day, register 93 — at-chance, not below-chance: the "
         "practical claim holds, the mechanism claim does not; "
         "composite ruling HOLD; bases-confirm rule registered)"),
        (f"Q2-H{6}", "**GRADED: YES** (2026-08-27, register 92, on "
         "row-level review — net reach 29.0% vs member range max "
         "12.8; the target-based recipe chain activates, first "
         "front-door step below)"),
        (f"Q3-H{6}", "**GRADED: YES x3** (2026-08-28, register 99, "
         "rows-confirm on the current emission — away net reach "
         "ger40 35.8 / nas100 29.0 / us30 41.9 vs range maxes 18.7 / "
         "19.2 / 16.7; the scalp's evidence base is now "
         "four-instrument, away rows carry claim status)"),
        ("Q1-H19", "**GRADED: NO** (the sitting 2026-08-28, register "
         "88 — the register's first grade; fwd London pooled −16.84 "
         "median, n=38; row accrues unchanged)"),
        ("Q2-H11", "≥30 FURTHER fwd London ger40fut S0-H11 "
         "R-NEXIT-EARLY trades from mint 2026-08-28 "
         f"(accrued: {_journal_q2h11()})"),
    ]
    for q, clock in q_lines:
        L.append(f"- **{q}** — {clock}")
    L.append("")

    # (d) recommendations awaiting decisions
    L += ["## Awaiting operator decisions", "",
          "- The 2026-08-28 sitting (register 88) cleared the standing "
          "batch: review labels resolved (H2 label withdrawn, H10 "
          "deprioritize enacted, S0-H"
          f"{9} keeps running), ratifications passed in one sweep "
          "(promote/deprioritize numbers, ±2pp band, session scoping, "
          "coil proxy, R-ARM15 N=1, 5-bar dedup; v0 recipes stand as "
          "history).",
          "- Scalp chain COMPLETE (register 94): R-SCALP-H"
          f"{6} (v0) registered, two counted arms (plain + "
          "refined-entry), all four gates ratified; runs in the "
          "journal from the next Part C emission, forward-graded "
          "under the row-level rule. Optimistic target fill "
          "declared. The v1 tighter stop is deferred — "
          "derivation-required from the forward non-reach EOD "
          "distribution.",
          f"- The H{6}-not-in-London composite: HOLD (register 93 — "
          "at-chance weakens the rationale; re-proposes only if "
          "below-chance suppression reappears on fresh accrual). "
          "August-vs-July regime texture routed to the "
          "sealed-window docket.",
          "- Standing deferrals: never-again fiat (register 90, "
          "option c; revisit when capture cells measure); "
          "R-SCOPED-BE waits on its register-92 gate (ranging-entry "
          "BE advantage beyond luck).",
          "- Next-sitting reads: matrix survivors · the co-fire "
          "consistency re-read (stands as emitted; accrual decides).",
          "- Open operator items: thin-tape probe (optional calendar); "
          "broker verifications (leverage/maintenance/minis).",
          ""]

    # (e) the map
    L += ["## Map — what answers what (reports/scoreboard/ unless noted)",
          "",
          "- **`reports/SIGNAL_POINTS.md`** — the assessment page: net "
          "points per signal across the stop-width ladder, per session, "
          "with the open-question conditioned views. THE first "
          "drill-down from this board. Read weekly.",
          "- `hypothesis_performance.md|.json` — how every signal grades "
          "(dual-convention). Read weekly.",
          "- `READING_GUIDE.md` — how to read the board. Read once, "
          "reread after convention changes.",
          "- `recipe_performance.md|.json` — what fires would have paid "
          "under explicit exits. Read weekly; values discussion input.",
          "- `excursion_geometry.md|.json` — stop-width + target-reach "
          "curves. Read at the v1 recipe-values discussion.",
          "- `bar_persistence.md|.json` — scalp viability: do fires "
          "persist bar-to-bar past spread, vs the random floor. Read "
          "weekly; scalp candidates go through their own registrations.",
          "- `narrative_survey.md|.json` — the sentence space with "
          "luck priced: every anchor × sequel class vs the permutation "
          "null; the two-chapter focal cell grades within the field. "
          "Read weekly. (Pilot archived: reports/archive/"
          "sequel_census.md.)",
          "- `conditioning_matrix.md|.json` — where signals work/fail by "
          f"state; grades Q1-H11/Q2-H{9}/Q1-H{6}. Read weekly.",
          "- `cofire.md|.json` — does cross-family agreement help "
          "(composites gate). Read weekly — the starved verdict is "
          "STALE (register 74-A5); re-read ordered.",
          "- `vwap_census.md|.json` / `drift_census.md|.json` — VWAP and "
          "drift verdicts (nothing survives / no base-rate change). Read "
          "on change only.",
          "- `location_census.md|.json` — exhaustion-family × volume map "
          "(starved; accruing). Read monthly.",
          "- `reports/archive/` — everything superseded, with dated "
          "reasons (ARCHIVE_LOG.md; register 75): flip-cut, the survey "
          "pilot, excursion profiles, organ #1's first output. Nothing "
          "deleted, ever.",
          "- `r2_experiment.md|.json` — the refinement question's "
          "evidence. Read once, at the R2 ruling.",
          "- `reports/forward/` — migration dossier. Read weekly.",
          "- **`reports/trades.csv` + `reports/weekly_summary.csv`** — "
          "the narrative trade layer (registers 76/77): the 4-variant "
          "trade journal (management ladder v2, context tags) and the "
          "per-sentence ISO-week rollup. `management_grades.csv` "
          "carries the MANDATORY vs-baseline line — no variant's net "
          "is quotable without it. `intra_trade_census.md` measures "
          "in-hold opposing narrative (register 78) before any "
          "narrative-management machinery. `journal_survey.md` prices "
          "the journal's own luck (register 80) — its survivors are "
          "question candidates, listed not minted. Tags post-hoc "
          "exploratory.",
          "- **`reports/forensics/` + `reports/trades_enriched.csv`** — "
          "trade forensics (register 84): per-market winner/loser "
          "separators vs a permutation null, exit-efficiency and "
          "winner-MAE design inputs, WATCH list, cross-market "
          "synthesis. Candidate-generation only — read at the "
          "operator+reviewer sitting; questions through the front "
          "door.",
          "- `reports/account_curves/` — the bankroll lens (registers "
          "83/86): per-strategy isolated accounts + `_LEADERBOARD.csv` "
          "with the B-RANDOM luck reference. Never evidence; runs on "
          "`--pot`.",
          "- `h6_refinement.md` — the scalp refinement program (register "
          "100): co-fire context census with a 3-of-4 discriminator, "
          "veto counterfactuals, time-cap derivation; v0 untouched, "
          "survivors are candidate v1 arms via the front door.",
          "- `zone_census.md` — the H4 key-zone conditioner, v2 "
          "strictness ladder (registers 95/96) — PARKED as the "
          "standing null (register 97): flat-to-negative density-vs-"
          "lift across 8 rungs, no freshness decay; accrues weekly, no "
          "further rungs without new evidence.",
          "- `underwater_census.md` + `thesis_campaign.md` — "
          "loser-cutting and the operator's trading loop, measured "
          "(register 87): survival curves, cut/BE ladders with "
          "floors, re-entry on the undeduped stream, thesis-campaign "
          "accounting vs random-thesis controls. Measurement before "
          "machinery; candidates via the front door.",
          "- `reports/backtest_v1.md` — the evidential pipeline + Part C "
          "index. The weekly 5-minute read.",
          "- `docs/backlog_status.md` — is everything moving. Glance "
          "weekly.", ""]
    return "\n".join(L)


def main():
    doc = generate()
    with open(os.path.join(ROOT, "reports", "DASHBOARD.md"), "w") as f:
        f.write(doc)
    print("dashboard -> reports/DASHBOARD.md")


if __name__ == "__main__":
    main()
